import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Dimensions matching atlas region ratio (512x320) scaled to scene
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Gradient colors: surface (#0b0b10) to paper (#e8ecf2)
  const colorInk = vec3(0.043, 0.043, 0.063);   // surface
  const colorPaper = vec3(0.91, 0.925, 0.95);   // paper
  const gradientNode = mix(colorInk, colorPaper, uv().y);

  // Temporary material without texture
  const material = new MeshBasicNodeMaterial();
  material.colorNode = gradientNode;

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load brushed metal texture
  const texturePromise = ctx.textureLoader.loadTexture(
    config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  );

  texturePromise.then((texture) => {
    material.map = texture;
    material.colorNode = mix(
      vec3(1, 1, 1), // preserve texture fully at bottom
      gradientNode,
      float(0.35)    // subtle gradient tint
    );
    material.needsUpdate = true;
  });

  // Text label "Collection 2" – headline size from design tokens (0.34 scene units)
  const text = ctx.fontAtlas.createText('Collection 2', {
    fontSize: 0.34,
    color: '#e8ecf2',            // paper
    align: 'center',
    maxWidthPx: 320,
  });

  text.position.set(0, 0, 0.01); // slightly in front of plane
  text.scale.set(1, 1, 1);
  group.add(text);

  // Handlers (none per spec)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    // Kill any GSAP timelines (none here)
    geometry.dispose();
    material.dispose();

    // Dispose texture once loaded
    texturePromise.then((tex) => tex.dispose()).catch(() => {});

    // Remove text (its atlas resources are managed externally)
    group.remove(text);
  };

  return group;
}
